   public String visit(AssignmentStatement n, String argu) {
      String _ret=null;
      n.f0.accept(this, "Assignment");
      n.f1.accept(this, argu);
      n.f2.accept(this, argu);
      n.f3.accept(this, argu);
      String varname = n.f0.f0.tokenImage;
      Integer regExp = addr.get(n.f2);
      if(localVars.containsKey(varname)){
         // local var
         Integer reg = localVars.get(varname);
         ir.genMoveTempTemp(reg, regExp);
      }
      else{
         // must be a class field
         Integer offset = classData.get(currClass).getVarPosition(varname);
         ir.genHStore(0, 4*(offset+1), regExp);
      }
      return _ret;
   }

