   /**
    * f0 -> PrimaryExpression()
    * f1 -> "&&"
    * f2 -> PrimaryExpression()
    */
   public String visit(AndExpression n, String argu) {
      String _ret=null;
      ir.genSingleLineComment("First Boolean Evaluation of && starts here");
      n.f0.accept(this, argu);
      ir.genSingleLineComment("First Boolean Evaluation of && ends here");
      n.f1.accept(this, argu);
      int regExp1 = addr.get(n.f0);
      int regAns = fresh();
      String label1 = freshLabel();
      String label2 = freshLabel();

      ir.genCJump(regExp1, label1);
      ir.genSingleLineComment("Second Boolean Evaluation of && starts here");
      n.f2.accept(this, argu);
      ir.genSingleLineComment("Second Boolean Evaluation of && end here");
      int regExp2 = addr.get(n.f2);
      ir.genCJump(regExp2, label1);
      ir.genMoveTempConst(regAns, 1);
      ir.genJump(label2);
      ir.gen(label1);
      ir.genMoveTempConst(regAns, 0);
      ir.gen(label2);
      ir.genSingleLineComment("Complete Boolean Evaluation of && ends here");

      addr.put(n, regAns);

      return _ret;
   }

   /**
    * f0 -> PrimaryExpression()
    * f1 -> "||"
    * f2 -> PrimaryExpression()
    */
   public String visit(OrExpression n, String argu) {
      String _ret=null;
      n.f0.accept(this, argu);
      n.f1.accept(this, argu);

      int regExp1 = addr.get(n.f0);
      int regAns = fresh();
      String label1 = freshLabel();
      String label2 = freshLabel();
      String label3 = freshLabel();
      String label4 = freshLabel();

      ir.genCJump(regExp1, label2);
      ir.gen(label1);
      ir.genMoveTempConst(regAns, 1);
      ir.genJump(label4);
      ir.gen(label2);
      n.f2.accept(this, argu);
      int regExp2 = addr.get(n.f2);
      ir.genCJump(regExp2, label3);
      ir.genJump(label1);
      ir.gen(label3);
      ir.genMoveTempConst(regAns, 0);
      ir.gen(label4);

      addr.put(n, regAns);
      return _ret;
   }

